async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) throw new RangeError("limit >= 1");
  const results = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      const index = next++;
      results[index] = await fn(items[index], index);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

function createLatestLoader(load, commit, onError) {
  let version = 0;
  return async function search(query) {
    const current = ++version;
    try {
      const data = await load(query);
      if (current === version) commit(data);
    } catch (error) {
      if (current === version) onError(error);
    }
  };
}
// load, commit и onError передаются приложением.

